import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Modal from '../../components/Modal';
import { Button, Input, Loading, ErrorState, EmptyState } from '../../components/ui';
import CategoryTabs from '../../components/menu/CategoryTabs';
import ProductCard from '../../components/menu/ProductCard';
import ProductForm from '../../components/menu/ProductForm';
import useMenu from '../../hooks/useMenu';
import useModifiers from '../../hooks/useModifiers';

const MenuPage = () => {
  const navigate = useNavigate();
  const {
    categories,
    products,
    loading,
    error,
    refetch,
    toggleAvailability,
    deleteProduct,
    duplicateProduct,
    reorderProducts,
  } = useMenu();
  const { modifiers } = useModifiers();

  const [showForm, setShowForm] = useState(false);
  const [editingProduct, setEditingProduct] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategoryTab, setActiveCategoryTab] = useState('all');
  const [draggedProductId, setDraggedProductId] = useState(null);

  const startCreate = () => {
    setEditingProduct(null);
    setShowForm(true);
  };

  const startEdit = (product) => {
    setEditingProduct(product);
    setShowForm(true);
  };

  const closeForm = () => setShowForm(false);

  const handleSaved = () => {
    setShowForm(false);
    refetch();
  };

  const handleDrop = (targetProduct) => {
    if (draggedProductId === null || draggedProductId === targetProduct.id || activeCategoryTab === 'all') return;
    reorderProducts(targetProduct.category_id, draggedProductId, targetProduct.id);
    setDraggedProductId(null);
  };

  if (loading) return <Loading />;
  if (error) return <ErrorState title="🍽️ Gestionar Menú" message={error} onRetry={refetch} />;

  const filteredProducts = products.filter((p) => {
    const matchesCategory = activeCategoryTab === 'all' || p.category_id === activeCategoryTab;
    const matchesSearch = !searchTerm || p.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  return (
    <div>
      <div className="flex justify-between items-center mb-2 flex-wrap gap-3">
        <h1 className="text-slate-200 text-[28px]">🍽️ Gestionar Menú</h1>
        <Button onClick={() => (showForm ? closeForm() : startCreate())}>+ Nuevo Plato</Button>
      </div>
      <p className="text-slate-500 text-[13px] mb-5">
        ¿Necesitas crear o reordenar categorías? Andá a{' '}
        <span onClick={() => navigate('/admin/categories')} className="text-sky-400 cursor-pointer underline">
          🗂️ Categorías
        </span>
        . ¿Necesitas crear nuevos grupos de opciones (ej. "Tipo de bebida")? Andá a{' '}
        <span onClick={() => navigate('/admin/modifiers')} className="text-sky-400 cursor-pointer underline">
          ⚙️ Modificadores
        </span>
        .
      </p>

      <CategoryTabs
        categories={categories}
        products={products}
        active={activeCategoryTab}
        onChange={setActiveCategoryTab}
      />

      <div className="mb-5 max-w-[360px]">
        <Input
          type="text"
          placeholder="🔍 Buscar producto por nombre..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {showForm && (
        <Modal title={editingProduct ? '✏️ Editar Producto' : 'Crear Producto'} onClose={closeForm} maxWidth={760}>
          <ProductForm
            product={editingProduct}
            categories={categories}
            allProducts={products}
            modifiers={modifiers}
            onSaved={handleSaved}
          />
        </Modal>
      )}

      {activeCategoryTab !== 'all' && (
        <p className="text-slate-500 text-xs mb-3">
          🔀 Arrastra las tarjetas para cambiar el orden en que aparecen en el menú.
        </p>
      )}

      <div className="grid gap-4" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))' }}>
        {filteredProducts.map((product) => (
          <ProductCard
            key={product.id}
            product={product}
            draggable={activeCategoryTab !== 'all'}
            isDragging={draggedProductId === product.id}
            onDragStart={() => setDraggedProductId(product.id)}
            onDrop={() => handleDrop(product)}
            onToggleAvailability={() => toggleAvailability(product.id, product.is_available)}
            onDuplicate={() => duplicateProduct(product.id)}
            onEdit={() => startEdit(product)}
            onDelete={() => deleteProduct(product.id)}
          />
        ))}
        {filteredProducts.length === 0 && (
          <EmptyState
            className="col-span-full"
            message="No hay productos que coincidan con la búsqueda/categoría."
          />
        )}
      </div>
    </div>
  );
};

export default MenuPage;
